function reviewValue(name) { updateReviewDirectories(); return reviewForm.elements.namedItem(name).value; }
function persistReview() { if (!reviewDocument) return; localStorage.setItem(reviewStorageKey, JSON.stringify({result_path: reviewDocument.result_path, review_path: reviewDocument.review_path, project_output_directory: reviewValue("project_output_directory"), review_output_directory: reviewValue("review_output_directory"), revision_output_directory: reviewValue("revision_output_directory"), export_output_directory: reviewValue("export_output_directory"), custom_paths: document.querySelector("#custom-review-paths").checked, applied_revision_path: appliedRevisionPath})); }
async function rememberReviewSession() { if (!reviewDocument) return; await postReview("session/save", {project_output_directory: reviewValue("project_output_directory"), result_path: reviewDocument.result_path, review_path: reviewDocument.review_path, review_output_directory: reviewValue("review_output_directory"), revision_output_directory: reviewValue("revision_output_directory"), export_output_directory: reviewValue("export_output_directory"), applied_revision_path: appliedRevisionPath}); }
